/*
 * prog24_query_string_parser – reproduced from the analysed binary
 *
 * Behaviour:
 *   * Reads one line from stdin (up to 2048 bytes, including the newline).
 *   * If no line is read, prints the literal string "NO_INPUT" and exits.
 *   * Otherwise treats the line as a URL‑query string:
 *         key1=val1&key2=val2&...
 *     Keys and values are URL‑decoded ( %XX → byte, '+' → space ).
 *   * For each key/value pair it prints:
 *         key=value\n
 *   * Empty values are allowed (e.g. "foo=&bar=baz").
 *   * Trailing CR/LF characters are ignored.
 *
 * The implementation follows the logic discovered in the decompiled
 * binary but is written in clear, idiomatic C.
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define LINE_MAX   0x800          /* 2048 bytes – same as the binary */
#define BUF_MAX    0x400          /* 1024 bytes – enough for keys/values */

/* ------------------------------------------------------------------ */
/* URL‑decode a string.
 *
 *  src   – pointer to the source string (may contain %XX escapes and '+')
 *  srclen – length of the source string (bytes to decode)
 *  dst   – destination buffer (must be large enough)
 *
 * The function writes a NUL‑terminated decoded string to dst.
 * It returns the number of bytes written (excluding the terminator).
 * ------------------------------------------------------------------ */
static size_t url_decode(const char *src, size_t srclen, char *dst)
{
    size_t i = 0, j = 0;
    while (i < srclen) {
        char c = src[i];
        if (c == '+') {
            dst[j++] = ' ';
            i++;
        } else if (c == '%' && i + 2 < srclen &&
                   isxdigit((unsigned char)src[i+1]) &&
                   isxdigit((unsigned char)src[i+2])) {
            /* Convert two hex digits to a byte */
            char hi = src[i+1];
            char lo = src[i+2];
            int val = (isdigit((unsigned char)hi) ? hi - '0' :
                      (toupper((unsigned char)hi) - 'A' + 10));
            val = (val << 4) + (isdigit((unsigned char)lo) ? lo - '0' :
                      (toupper((unsigned char)lo) - 'A' + 10));
            dst[j++] = (char)val;
            i += 3;
        } else {
            dst[j++] = c;
            i++;
        }
    }
    dst[j] = '\0';
    return j;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    static char line[LINE_MAX];
    static char key_buf[BUF_MAX];
    static char val_buf[BUF_MAX];

    /* Read a line from stdin */
    if (fgets(line, sizeof(line), stdin) == NULL) {
        puts("NO_INPUT");
        return 0;
    }

    /* Strip trailing CR and LF (if any) */
    size_t len = strlen(line);
    while (len > 0 && (line[len-1] == '\n' || line[len-1] == '\r')) {
        line[--len] = '\0';
    }

    /* Parse the query string */
    const char *p = line;
    while (*p) {
        /* ---- parse key ---- */
        const char *key_start = p;
        while (*p && *p != '=' && *p != '&')
            ++p;
        size_t key_len = p - key_start;

        /* ---- parse value ---- */
        const char *val_start = NULL;
        size_t val_len = 0;
        if (*p == '=') {
            ++p;                     /* skip '=' */
            val_start = p;
            while (*p && *p != '&')
                ++p;
            val_len = p - val_start;
        } else {
            /* No '=', value is empty */
            val_start = p;           /* points to '&' or end */
            val_len = 0;
        }

        /* Decode and print */
        url_decode(key_start, key_len, key_buf);
        url_decode(val_start, val_len, val_buf);
        printf("%s=%s\n", key_buf, val_buf);

        /* Skip '&' separator, if present */
        if (*p == '&')
            ++p;
    }

    return 0;
}
